-- V-026 (run O1, ADMIN-2): after 026-admin-actions.sql
-- Read only, in a read-only transaction. Each row is: ok or KO | what | the number found. Never a name, an e-mail or a row of a person.
-- From the Verify lines of the file's header: what 026 must leave, each as a row that stops the part when it is KO.
begin transaction read only;
select case when ok is true then 'ok' else 'KO' end, what, coalesce(got, '-') from (values
  (1, 'admin_actions avec RLS, aucune policy', (select count(*) = 1 from pg_class c where c.oid = to_regclass('public.admin_actions') and c.relrowsecurity and not exists (select 1 from pg_policy p where p.polrelid = c.oid)), (select count(*)::text from pg_class c where c.oid = to_regclass('public.admin_actions') and c.relrowsecurity)),
  (2, 'les 9 colonnes du journal (id, at, admin_id, site_id, action, target_type, target_id, detail, request_id)', (select count(*) = 9 from information_schema.columns where table_schema = 'public' and table_name = 'admin_actions' and column_name in ('id', 'at', 'admin_id', 'site_id', 'action', 'target_type', 'target_id', 'detail', 'request_id')), (select count(*)::text from information_schema.columns where table_schema = 'public' and table_name = 'admin_actions')),
  (3, 'site_id : clé étrangère validée vers sites, et aucune clé étrangère sur admin_id', (select count(*) = 1 from pg_constraint where conrelid = to_regclass('public.admin_actions') and conname = 'admin_actions_site_id_fkey' and contype = 'f' and convalidated and confrelid = 'public.sites'::regclass) and (select count(*) = 0 from pg_constraint where conrelid = to_regclass('public.admin_actions') and contype = 'f' and conname <> 'admin_actions_site_id_fkey'), (select count(*)::text from pg_constraint where conrelid = to_regclass('public.admin_actions') and contype = 'f')),
  (4, '5 checks validés (action, target_type, target_id, detail, request_id)', (select count(*) = 5 and bool_and(convalidated) from pg_constraint where conrelid = to_regclass('public.admin_actions') and contype = 'c' and conname in ('admin_actions_action_check', 'admin_actions_target_type_check', 'admin_actions_target_id_check', 'admin_actions_detail_check', 'admin_actions_request_id_check')), (select count(*)::text from pg_constraint where conrelid = to_regclass('public.admin_actions') and contype = 'c')),
  (5, '2 index (site puis date, admin puis date)', (select count(*) = 2 from pg_indexes where schemaname = 'public' and tablename = 'admin_actions' and indexname in ('admin_actions_site_at_idx', 'admin_actions_admin_at_idx')), (select count(*)::text from pg_indexes where schemaname = 'public' and tablename = 'admin_actions' and indexname in ('admin_actions_site_at_idx', 'admin_actions_admin_at_idx'))),
  (6, 'déclencheur actif : aucune modification ni suppression d''une ligne', (select count(*) = 1 from pg_trigger where tgrelid = to_regclass('public.admin_actions') and tgname = 'trg_admin_actions_append_only' and tgenabled = 'O' and not tgisinternal) and (select pg_get_triggerdef(oid) ~ 'BEFORE DELETE OR UPDATE' from pg_trigger where tgrelid = to_regclass('public.admin_actions') and tgname = 'trg_admin_actions_append_only'), (select count(*)::text from pg_trigger where tgrelid = to_regclass('public.admin_actions') and not tgisinternal)),
  (7, 'la fonction du déclencheur fermée à anon et authenticated', (select count(*) = 1 and bool_and(not has_function_privilege('anon', oid, 'execute') and not has_function_privilege('authenticated', oid, 'execute')) from pg_proc where pronamespace = 'public'::regnamespace and proname = 'admin_actions_append_only'), (select count(*)::text from pg_proc where pronamespace = 'public'::regnamespace and proname = 'admin_actions_append_only')),
  (8, 'anon et authenticated : aucun droit sur la table ni sur sa séquence', (select count(*) = 0 from (values ('anon'), ('authenticated')) as r(role) cross join (values ('select'), ('insert'), ('update'), ('delete'), ('truncate'), ('references'), ('trigger')) as p(priv) where to_regclass('public.admin_actions') is null or has_table_privilege(r.role, 'public.admin_actions', p.priv)) and (select count(*) = 0 from (values ('anon'), ('authenticated')) as r(role) cross join (values ('usage'), ('select'), ('update')) as p(priv) where to_regclass('public.admin_actions_id_seq') is null or has_sequence_privilege(r.role, 'public.admin_actions_id_seq', p.priv)), null),
  (9, 'service_role : select et insert, ni update ni delete', (select has_table_privilege('service_role', 'public.admin_actions', 'select') and has_table_privilege('service_role', 'public.admin_actions', 'insert') and not has_table_privilege('service_role', 'public.admin_actions', 'update') and not has_table_privilege('service_role', 'public.admin_actions', 'delete')), null)
) as c(n, what, ok, got) order by n;
rollback;
